
import os
import subprocess
import requests
import shutil

def run_command(cmd, cwd=None):
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True, cwd=cwd)
    return result.stdout.strip(), result.stderr.strip(), result.returncode

def setup_github_pages(repo_path, github_username, repo_name, token):
    if not os.path.isdir(repo_path):
        return "❌ Provided repo path does not exist.", None

    index_path = os.path.join(repo_path, "index.html")
    if not os.path.isfile(index_path):
        # Search for index.html in subdirectories
        found = False
        for root, dirs, files in os.walk(repo_path):
            if "index.html" in files:
                index_html_full = os.path.join(root, "index.html")
                shutil.copy(index_html_full, os.path.join(repo_path, "index.html"))
                found = True
                break
        if not found:
            return "❌ No index.html found in project structure.", None

    # Add .nojekyll
    nojekyll_path = os.path.join(repo_path, ".nojekyll")
    with open(nojekyll_path, "w") as f:
        f.write("")

    # Initialize git if needed
    if not os.path.isdir(os.path.join(repo_path, ".git")):
        run_command("git init", cwd=repo_path)
        run_command("git branch -M main", cwd=repo_path)
        run_command(f"git remote add origin https://github.com/{github_username}/{repo_name}.git", cwd=repo_path)

    # Commit and push changes
    run_command("git add .", cwd=repo_path)
    run_command("git commit -m 'Setup GitHub Pages automatically'", cwd=repo_path)
    run_command("git push -u origin main", cwd=repo_path)

    # Call GitHub API to enable Pages
    headers = {
        "Authorization": f"token {token}",
        "Accept": "application/vnd.github+json"
    }

    enable_pages_payload = {
        "source": {
            "branch": "main",
            "path": "/"
        }
    }

    api_url = f"https://api.github.com/repos/{github_username}/{repo_name}/pages"
    response = requests.post(api_url, headers=headers, json=enable_pages_payload)

    if response.status_code in [201, 204]:
        return "✅ GitHub Pages enabled successfully!", f"https://{github_username}.github.io/{repo_name}/"
    else:
        return f"❌ GitHub API error: {response.status_code} - {response.text}", None

if __name__ == "__main__":
    print("🔧 GitHub Pages Auto-Fix Script")

    repo_path = input("📁 Enter full local repo path: ").strip()
    github_username = input("👤 Enter your GitHub username: ").strip()
    repo_name = input("📦 Enter your GitHub repository name: ").strip()
    token = input("🔑 Enter your GitHub Personal Access Token: ").strip()

    status, url = setup_github_pages(repo_path, github_username, repo_name, token)
    print(status)
    if url:
        print("🌐 Your live site:", url)
